mapper.update:
UPDATE collect_phase_steps
SET status = 'skipped', message = #{message}, updated_at = NOW(3)
WHERE task_id = #{taskId} AND step_key = #{stepKey}

mapper.select:
SELECT status
FROM collect_phase_steps
WHERE task_id = #{taskId}
  AND step_key = #{stepKey}
LIMIT 1

mapper.update:
UPDATE hermes_user_dialogues
SET content = #{content}
WHERE task_id = #{taskId} AND msg_type = 'thoughts_final'

mapper.select:
SELECT task_id, phase, mcp_server, tool_name
FROM hermes_tool_outputs
WHERE task_id = #{taskId}
  AND phase = #{phase}
  AND status = 'success'
ORDER BY id ASC
